{
  "name": "dsh-plugin-update-fixture-c",
  "version": "0.0.2",
  "private": false,
  "type": "module",
  "description": "纯目标（无更新接线，只被批量集成方更新） [TEST ONLY sed: selftest fixture for dsh-plugin-update]",
  "license": "MIT",
  "main": "./lib/index.js",
  "exports": {
    ".": "./lib/index.js",
    "./client": "./lib/client.js",
    "./package.json": "./package.json"
  },
  "files": [
    "lib",
    "cordis.patch.yml"
  ],
  "engines": {
    "dsh": ">=0.2.0-rc.2 <0.3.0-0"
  },
  "dependencies": {},
  "dsh": {
    "client": {
      "platform": "web",
      "inject": []
    },
    "bundle": {
      "patch": "./cordis.patch.yml"
    }
  }
}

// [TEST ONLY] 夹具纯目标 host half（#265 生成产物，勿手改；源模板 = selftest/fixtures/templates/target）
export const name = 'dsh-plugin-update-fixture-c'
export const inject: string[] = []
export const BUILD_TAG = 'host v0.0.2'

// 纯目标不注册电话、不连更新链：只求被宿主当作普通插件加载成功。
export function apply(): void {}

// [TEST ONLY] 夹具纯目标 client half（#266 生成产物，勿手改；源模板 = selftest/fixtures/templates/target）
declare function require(id: string): any
declare const exports: any

const React = require('react')
const PLUGIN_ID = 'dsh-plugin-update-fixture-c'
const BUILD_TAG = 'client v0.0.2'
const FIXTURE_KEY = 'c'
const BADGE_TEXT = '夹具 C · client v0.0.2（新版 · T4-20261103T093814-p11）'

// 纯目标：故意不 require dsh-plugin-update 的任何子路径，也不挂任何更新入口/面板。
function TargetBadge() {
  return React.createElement('div', {
    className: 'dsh-fixture-card dsh-fixture-target',
    'data-fixture': FIXTURE_KEY,
    'data-fixture-ui': 'none',
    'data-update-wiring': 'none',
    'data-build-tag': BUILD_TAG,
    style: { position: 'fixed', left: 16, bottom: 16, width: 220, zIndex: 2147483000, pointerEvents: 'auto', background: '#eef7ee', color: '#12301a', border: '1px solid rgba(32,120,64,.45)', borderRadius: 10, padding: '6px 10px', fontSize: 12, boxShadow: '0 8px 24px rgba(0,0,0,.2)' },
  }, BADGE_TEXT)
}

function apply(ctx: any): void {
  ctx.slots.inject('shell.overlay', () => ctx.slots.register({
    name: 'shell.overlay',
    id: PLUGIN_ID + '-overlay',
    label: () => PLUGIN_ID,
  }, () => React.createElement(TargetBadge)))
}

const inject = ['slots']
exports.apply = apply
exports.inject = inject
